; calls.asm -- appendix D: the routines, for every line and column
; generated by genD.py
        INCLUDE "msx.inc"
        OUTPUT "calls.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; The display off, so that the answers can go to the VRAM at any speed.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off

; pcalc: every line, 0 to 191, and 32 columns, x = 8c + ((c + y) AND 7)
s_pcalc: VRAM_WRITE $0000
        ld c, 0                 ; y
y_pcalc: ld b, 0                ; 8c
x_pcalc: ld a, b
        rrca
        rrca
        rrca                    ; c
        add a, c
        and 7
        or b
        ld b, a                 ; x
        push bc
        call pcalc
        ld a, l
        out (VDP_DATA), a
        ld a, h
        out (VDP_DATA), a       ; HL, low byte first
        pop bc
        ld a, b
        and $F8
        add a, 8
        ld b, a
        jr nz, x_pcalc
        inc c
        ld a, c
        cp 192
        jr nz, y_pcalc
e_pcalc: nop                    ; measD.py reads the VRAM here

; ptab: every line, 0 to 191, and 32 columns, x = 8c + ((c + y) AND 7)
s_ptab: VRAM_WRITE $0000
        ld c, 0                 ; y
y_ptab: ld b, 0                 ; 8c
x_ptab: ld a, b
        rrca
        rrca
        rrca                    ; c
        add a, c
        and 7
        or b
        ld b, a                 ; x
        push bc
        call ptab
        ld a, l
        out (VDP_DATA), a
        ld a, h
        out (VDP_DATA), a       ; HL, low byte first
        pop bc
