; pdown: every line, 0 to 190, and 32 columns, x = 8c + ((c + y) AND 7)
s_pdown: VRAM_WRITE $0000
        ld c, 0                 ; y
y_pdown: ld b, 0                ; 8c
x_pdown: ld a, b
        rrca
        rrca
        rrca                    ; c
        add a, c
        and 7
        or b
        ld b, a                 ; x
        push bc
        call pcalc
        call pdown
        ld a, l
        out (VDP_DATA), a
        ld a, h
        out (VDP_DATA), a       ; HL, low byte first
        pop bc
        ld a, b
        and $F8
