e_pdown: nop                    ; measD.py reads the VRAM here

; ncalc: every line, 0 to 191, and 32 columns, x = 8c + ((c + y) AND 7)
s_ncalc: VRAM_WRITE $0000
        ld c, 0                 ; y
y_ncalc: ld b, 0                ; 8c
x_ncalc: ld a, b
        rrca
        rrca
        rrca                    ; c
        add a, c
        and 7
        or b
        ld b, a                 ; x
        push bc
        call ncalc
        ld a, l
        out (VDP_DATA), a
        ld a, h
        out (VDP_DATA), a       ; HL, low byte first
        pop bc
        ld a, b
        and $F8
        add a, 8
        ld b, a
