e_ncalc: nop                    ; measD.py reads the VRAM here

; npage: every line, 0 to 191, and 32 columns, x = 8c + ((c + y) AND 7)
s_npage: VRAM_WRITE $0000
        ld c, 0                 ; y
y_npage: ld b, 0                ; 8c
x_npage: ld a, b
        rrca
        rrca
        rrca                    ; c
        add a, c
        and 7
        or b
        ld b, a                 ; x
        push bc
        call npage
        ld a, l
        out (VDP_DATA), a
        ld a, h
        out (VDP_DATA), a       ; HL, low byte first
        pop bc
