        and $F8
        add a, 8
        ld b, a
        jr nz, x_npage
        inc c
        ld a, c
        cp 192
        jr nz, y_npage
e_npage: nop                    ; measD.py reads the VRAM here

; each routine once, with its CALL, between two labels the debugger times
        ld bc, $4D85            ; x = 77, y = 133
a0:     call pcalc
b0:     nop
        ld bc, $4D85            ; x = 77, y = 133
a1:     call ptab
b1:     nop
        ld bc, $4D85            ; x = 77, y = 133
a2:     call ppage
b2:     nop
        ld bc, $4D85            ; x = 77, y = 133
        call pcalc
a3:     call pdown
b3:     nop
        ld bc, $4D87            ; x = 77, y = 135
        call pcalc
a4:     call pdown
b4:     nop
        ld bc, $4D85            ; x = 77, y = 133
a5:     call ncalc
b5:     nop
        ld bc, $4D85            ; x = 77, y = 133
a6:     call npage
b6:     nop
done:   jr done

; pcalc: B = x, C = y -> HL = the pattern byte of (x, y), the BIOS's layout:
; H = y >> 3, L = (x AND $F8) OR (y AND 7). Uses A.
pcalc:  ld a, c                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8: y >> 3
        ld h, a                 ;  5
        ld a, b                 ;  5
        xor c                   ;  5
        and $F8                 ;  8
        xor c                   ;  5: x's bits 7-3, y's 2-0
        ld l, a                 ;  5
        ret                     ; 11

; ptab: the same from patrow, a word a line. Uses A, DE.
ptab:   ld l, c                 ;  5
        ld h, 0                 ;  8
        add hl, hl              ; 12: y x 2
        ld de, patrow           ; 11
        add hl, de              ; 12
        ld a, (hl)              ;  8
        inc hl                  ;  7
        ld h, (hl)              ;  8
        ld l, a                 ;  5: patrow's entry for y
        ld a, b                 ;  5
        and $F8                 ;  8
        or l                    ;  5
        ld l, a                 ;  5
        ret                     ; 11

; ppage: the same from pathi and patlo, a byte a line on two pages. Uses A.
ppage:  ld h, high pathi        ;  8
        ld l, c                 ;  5
        ld a, b                 ;  5
        and $F8                 ;  8
        inc h                   ;  5: patlo
        or (hl)                 ;  8
        dec h                   ;  5: pathi
        ld h, (hl)              ;  8
        ld l, a                 ;  5
        ret                     ; 11

; pdown: HL = the pattern byte of (x, y) -> of (x, y + 1), the BIOS's
; layout, y < 191. Uses A.
pdown:  inc l                   ;  5
        ld a, l                 ;  5
        and 7                   ;  8
        ret nz                  ; 12 out, 6 on: seven lines in eight
        ld a, l                 ;  5: the next row of characters
        sub 8                   ;  8
        ld l, a                 ;  5
        inc h                   ;  5
        ret                     ; 11

; ncalc: B = x, C = y -> HL = where the name of (x, y) is: $1800 + (y >> 3) x 32 +
; (x >> 3). Uses A.
ncalc:  ld a, c                 ;  5
        and $F8                 ;  8
        ld l, a                 ;  5
        ld h, 6                 ;  8: $0600 + (y AND $F8)
        add hl, hl              ; 12
        add hl, hl              ; 12: x 4, $1800 + (y >> 3) x 32
        ld a, b                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8: x >> 3
        or l                    ;  5
        ld l, a                 ;  5
        ret                     ; 11

; npage: the same from namhi and namlo. Uses A.
npage:  ld h, high namhi        ;  8
        ld l, c                 ;  5
        ld a, b                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8
        inc h                   ;  5: namlo
        or (hl)                 ;  8
        dec h                   ;  5: namhi
        ld h, (hl)              ;  8
        ld l, a                 ;  5
        ret                     ; 11

        INCLUDE "tables.inc"
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
